import numpy as np

from strategy import run_seed

N_SEEDS = 50
N_BARS = 2000


def t_stat(pnls):
    arr = np.asarray(pnls, dtype=float)
    return arr.mean() / (arr.std(ddof=1) / np.sqrt(len(arr)))


def run_harness(n_seeds=N_SEEDS, n_bars=N_BARS, base_seed=12345):
    """Returns summary stats for honest vs. lookahead variants on both series."""
    out = {}
    for variant, lookahead in (("honest", False), ("lookahead", True)):
        ou_pnls, rw_pnls = [], []
        for i in range(n_seeds):
            ou_pnl, rw_pnl = run_seed(base_seed + i, n_bars, lookahead=lookahead)
            ou_pnls.append(ou_pnl)
            rw_pnls.append(rw_pnl)
        ou_pnls = np.array(ou_pnls)
        rw_pnls = np.array(rw_pnls)
        out[variant] = {
            "ou_mean": ou_pnls.mean(),
            "ou_tstat": t_stat(ou_pnls),
            "rw_mean": rw_pnls.mean(),
            "rw_tstat": t_stat(rw_pnls),
        }
    return out


if __name__ == "__main__":
    res = run_harness()
    for variant, s in res.items():
        print(
            f"[{variant:>9}] OU: mean={s['ou_mean']:+8.3f}  t={s['ou_tstat']:+7.2f}   "
            f"RW: mean={s['rw_mean']:+8.3f}  t={s['rw_tstat']:+6.2f}"
        )
